mapper.select:
SELECT t.id,t.owner_id,t.purpose,t.status,t.revision,t.title,t.provider,t.model,t.currency,t.manifest_json,t.manifest_hash,
  t.configuration_fingerprint,t.authorization_epoch,t.current_attempt_id,t.attempt_count,t.candidate_json,
  t.error_code,t.created_at,t.updated_at
FROM ai_comparison c JOIN ai_task t ON t.owner_id=c.owner_id AND t.id=c.task_id
WHERE c.owner_id=#{owner} AND c.comparison_id=#{comparisonId}
AND t.id > #{cursor}
ORDER BY t.id LIMIT #{limit}

SELECT COUNT(*) FROM ai_comparison c JOIN ai_task t ON t.owner_id=c.owner_id AND t.id=c.task_id
WHERE c.owner_id=#{owner} AND c.comparison_id=#{comparisonId}
  AND t.status IN ('QUEUED','RUNNING','VALIDATING','CANCEL_REQUESTED')
AND c.task_id <> #{excludedTaskId}
